package com.iare.club.controller;import com.iare.club.service.*;import java.util.Map;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/payments/webhooks")public class PaymentWebhookController{private final PaymentWebhookService service;public PaymentWebhookController(PaymentWebhookService s){service=s;}
 @PostMapping("/youpi")ResponseEntity<?> youpi(@RequestBody byte[] raw,@RequestHeader(value="X-Gateway-Signature",required=false)String sig,@RequestHeader(value="X-Gateway-Signature-V2",required=false)String sig2,@RequestHeader(value="X-Gateway-Timestamp",required=false)String time,@RequestHeader(value="X-Gateway-Delivery-Id",required=false)String delivery){try{service.youpi(raw,sig,sig2,time,delivery);return ResponseEntity.ok(Map.of("received",true));}catch(DepositService.FinancialException e){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error",e.getMessage()));}}
 @PostMapping("/authorized-provider")ResponseEntity<?> authorized(@RequestBody byte[] raw,@RequestHeader(value="X-Provider-Signature",required=false)String sig,@RequestHeader(value="X-Provider-Signature-V2",required=false)String sig2,@RequestHeader(value="X-Provider-Timestamp",required=false)String time,@RequestHeader(value="X-Provider-Delivery-Id",required=false)String delivery){try{service.authorized(raw,sig,sig2,time,delivery);return ResponseEntity.ok(Map.of("received",true));}catch(DepositService.FinancialException e){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error",e.getMessage()));}}
}
